+  if (args.length === 0) {
+    console.log('用法: node validate-jsonl.js <文件路径>');
+    process.exit(1);
+  }
+
+  const filePath = args[0];
+
+  if (!fs.existsSync(filePath)) {
+    console.error(`文件错误: ${filePath} 不存在`);
