+  const lines = content.split(/\r?\n/);
+
+  let totalLines = 0;
+  let validCount = 0;
+  let errorCount = 0;
+
+  for (let i = 0; i < lines.length; i++) {
+    const line = lines[i].trim();
+    if (line === '') continue;
+
+    totalLines++;
+
+    try {
+      JSON.parse(line);
+      validCount++;
+    } catch (e) {
+      errorCount++;
+      console.log(`第 ${i + 1} 行: ${e.message}`);
+    }
+  }
+
+  console.log(`\n总计: ${totalLines} 行`);
+  console.log(`合法JSON: ${validCount} 行`);
+  console.log(`错误JSON: ${errorCount} 行`);
